if (!ctx.cam) R3.begin(ctx);
const mid = ctx.mid;
const T = (i) => Math.max(S, W[i] - 0.05);
const tx = (x, y, html, o, lh) => { const e = R3.text(x, y, html, o); e.style.lineHeight = lh + 'px'; e.style.whiteSpace = 'nowrap'; return e; };
const swap = (el, t, txt) => {
  tl.to(el, { autoAlpha: 0, duration: .12, ease: 'power1.in' }, t);
  tl.set(el, { textContent: txt }, t + .12);
  tl.to(el, { autoAlpha: 1, duration: .18, ease: 'power1.out' }, t + .12);
};

/* ---------- flat avatars: solid linear fills + offset shadow only ---------- */
const PAL = [['#ff6b6b', '#5f27cd'], ['#feca57', '#ff6b6b'], ['#48dbfb', '#0abde3'], ['#1dd1a1', '#10ac84'], ['#a29bfe', '#6c5ce7'],
  ['#fd79a8', '#e84393'], ['#fab1a0', '#e17055'], ['#81ecec', '#00cec9'], ['#ffeaa7', '#fdcb6e'], ['#74b9ff', '#0984e3']];
const ava = (x, y, d, k, parent, shadow) => {
  const [a, b] = PAL[(k + 3) % PAL.length];
  return R3.mk('div', 'r3-el', Object.assign(R3.box(x, y, d, d), { position: 'absolute', borderRadius: '50%', boxSizing: 'border-box',
    background: `linear-gradient(145deg, ${a} 0%, ${b} 100%)`, boxShadow: shadow || '0 4px 10px rgba(0,0,0,.45)' }), parent || mid);
};

/* ---------- static near-black hairline grid (flat, no mask, no motion) ---------- */
R3.mk('div', '', { position: 'absolute', left: '30px', top: '300px', width: '1020px', height: '534px', pointerEvents: 'none',
  backgroundImage: 'linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px)',
  backgroundSize: '48px 48px' }, mid);

/* connectors live under the phone so they tuck behind the bezel */
const svg = R3.svgLayer(mid);

/* ---------- geometry ---------- */
const PX = 500, PY = 312, PW = 520, PH = 510;
const SW = 496, SH = 486;
const ROW0 = 84, PITCH = 66, RH = 58, RX = 12, RW = SW - 24;
const slotY = (k) => ROW0 + k * PITCH;
const rowCY = (k) => PY + 12 + slotY(k) + 29;

/* ---------- HERO: phone with Requests inbox ---------- */
const phone = R3.card(PX, PY, PW, PH, null, { borderRadius: '52px', border: '3px solid rgba(255,255,255,.78)' });
const scr = R3.mk('div', 'r3-screen', Object.assign(R3.box(9, 9, SW, SH), { position: 'absolute', borderRadius: '42px', overflow: 'hidden', background: '#0a0b0f' }), phone);
scr.dataset.device = '1';
R3.mk('div', '', Object.assign(R3.box((SW - 104) / 2, 8, 104, 26), { position: 'absolute', borderRadius: '14px', background: '#000' }), scr);
tx(36, 12, '9:41', { size: 15, weight: 600, parent: scr }, 18);
tx(SW - 98, 12, '5G<span style="display:inline-block;width:24px;height:11px;border:1.5px solid rgba(255,255,255,.8);border-radius:3px;margin-left:7px;vertical-align:-1px;background:linear-gradient(90deg,rgba(255,255,255,.85) 68%,transparent 68%)"></span>', { size: 14, weight: 600, parent: scr }, 18);
tx(20, 34, '‹', { size: 30, weight: 500, parent: scr }, 34);
const appTitle = tx(48, 40, 'Requests (<span>38</span>)', { size: 22, weight: 700, parent: scr }, 28);
const appCount = appTitle.querySelector('span');
tx(SW - 130, 45, 'Delete all', { size: 15, weight: 500, parent: scr, color: 'rgba(255,255,255,.45)', w: 104, align: 'right' }, 20);
R3.mk('div', '', Object.assign(R3.box(0, 76, SW, 1), { position: 'absolute', background: 'rgba(255,255,255,.1)' }), scr);

function makeRow(slot, d, unread) {
  const r = R3.mk('div', 'r3-el', Object.assign(R3.box(RX, slotY(slot), RW, RH), { position: 'absolute', boxSizing: 'border-box', borderRadius: '14px',
    background: 'rgba(255,255,255,.05)', border: '1px solid rgba(255,255,255,.08)', filter: 'grayscale(0)' }), scr);
  const av = ava(8, 6, 44, d.k, r, '0 3px 6px rgba(0,0,0,.4)');
  const h = tx(64, 4, d.handle, { size: 18, weight: 700, parent: r }, 22);
  const tm = tx(RW - 68, 6, d.time, { size: 14, weight: 500, parent: r, color: 'rgba(255,255,255,.45)', w: 50, align: 'right' }, 18);
  const pv = tx(64, 34, d.preview, { size: 16, weight: 500, parent: r, color: 'rgba(255,255,255,.72)', w: RW - 64 - 44 }, 20);
  Object.assign(pv.style, { overflow: 'hidden', textOverflow: 'ellipsis' });
  let dot = null;
  if (unread) dot = R3.mk('div', '', Object.assign(R3.box(RW - 26, 39, 9, 9), { position: 'absolute', borderRadius: '50%', background: '#5aa9ff' }), r);
  return { r, av, h, tm, pv, dot };
}
const mira = makeRow(0, { handle: '@mira.cuts', preview: 'how do i blow up in a week??', time: '2m', k: 0 });
const jay  = makeRow(1, { handle: '@jayden.wav', preview: 'day 3… 14 views 😩', time: '9m', k: 2 });
const lexi = makeRow(2, { handle: '@lexi.mp4', preview: 'is there a faster way', time: '21m', k: 5 });
const kai  = makeRow(0, { handle: '@kai.makes', preview: 'repost my page fam? 🙏', time: 'now', k: 4 }, true);
const nova = makeRow(1, { handle: '@nova.lux', preview: '1 story share pls', time: 'now', k: 7 }, true);
const tre  = makeRow(2, { handle: '@tre.visuals', preview: "tag me, it'd change everything", time: 'now', k: 1 }, true);
const older = [mira.r, jay.r, lexi.r];

/* decline stamp (inside kai row, inside screen) */
const stamp = R3.mk('div', 'r3-el', { position: 'absolute', left: (RW - 178) + 'px', top: '10px', padding: '5px 12px', border: '2.5px solid #ff4d5e',
  borderRadius: '8px', color: '#ff4d5e', fontSize: '19px', fontWeight: '800', lineHeight: '24px', letterSpacing: '.04em',
  background: 'rgba(255,77,94,.12)', whiteSpace: 'nowrap' }, kai.r, '✕ Declined');

/* match-cut avatar clone (inside screen) */
const bigAva = ava((SW - 150) / 2, 150, 150, 4, scr, '0 14px 30px rgba(0,0,0,.55)');
Object.assign(bigAva.style, { border: '4px solid #0a0b0f', outline: '2px solid rgba(255,255,255,.5)', transformOrigin: '0 0' });
const bigName = tx(0, 318, '@kai.makes', { size: 24, weight: 700, parent: scr, w: SW, align: 'center' }, 28);
const bigSub = tx(0, 356, '3 posts · 212 followers', { size: 16, weight: 500, parent: scr, w: SW, align: 'center', color: 'rgba(255,255,255,.55)' }, 20);

/* ---------- SUPPORT: quit chip ---------- */
const quitChip = R3.chip(60, 318, 'avg time to quit: 11 days', null);
Object.assign(quitChip.style, { background: 'transparent', border: '1.5px solid rgba(255,255,255,.8)', color: '#fff', fontSize: '20px',
  lineHeight: '24px', padding: '7px 16px', borderRadius: '999px', boxShadow: 'none', whiteSpace: 'nowrap' });

/* ---------- SUPPORT: mini posting calendar ---------- */
const CX = 60, CY = 376, CWd = 320, CH = 180;
const cal = R3.card(CX, CY, CWd, CH);
tx(24, 16, 'Posting log', { size: 20, weight: 700, parent: cal }, 24);
const calS = tx(CWd - 140, 19, 'on track', { size: 15, weight: 600, parent: cal, color: '#3dff8b', w: 116, align: 'right' }, 20);
const sqs = [], ice = [];
['▶ 120', '▶ 41', '▶ 14'].forEach((v, i) => {
  const x = 36 + i * 88;
  const sq = R3.mk('div', 'r3-el', Object.assign(R3.box(x, 54, 72, 72), { position: 'absolute', boxSizing: 'border-box', borderRadius: '12px', overflow: 'hidden',
    background: 'linear-gradient(135deg, rgba(61,255,139,.55), rgba(16,172,132,.42))', border: '1px solid rgba(61,255,139,.35)',
    filter: 'grayscale(0) brightness(1)' }), cal);
  tx(8, 48, v, { size: 13, weight: 700, parent: sq, color: 'rgba(0,0,0,.62)' }, 16);
  ice.push(R3.mk('div', '', Object.assign(R3.box(0, 0, 72, 72), { position: 'absolute',
    background: i < 2 ? 'linear-gradient(160deg, rgba(205,228,255,.38), rgba(120,150,190,.14))'
                      : 'repeating-linear-gradient(45deg, rgba(170,172,182,.62) 0 6px, rgba(48,50,58,.92) 6px 12px)' }), sq));
  tx(x, 140, 'Day ' + (i + 1), { size: 14, weight: 600, parent: cal, color: 'rgba(255,255,255,.5)', w: 72, align: 'center' }, 18);
  sqs.push(sq);
});

/* ---------- SUPPORT: request counter card ---------- */
const KX = 60, KY = 576, KW = 320, KH = 246;
const cnt = R3.card(KX, KY, KW, KH);
tx(24, 18, 'Message requests', { size: 18, weight: 600, parent: cnt, color: 'rgba(255,255,255,.6)' }, 22);
const bigNum = tx(22, 44, '38', { size: 76, weight: 800, parent: cnt }, 84);
const plus = R3.mk('div', 'r3-el', { position: 'absolute', left: '146px', top: '72px', padding: '4px 12px', borderRadius: '999px',
  border: '1.5px solid rgba(127,184,255,.8)', color: '#a8d0ff', fontSize: '17px', fontWeight: '700', lineHeight: '22px', whiteSpace: 'nowrap' }, cnt, '+3 new');
const barH = [24, 32, 20, 38, 30, 44, 56];
const bars = barH.map((h, i) => R3.mk('div', '', Object.assign(R3.box(24 + i * 40, 206 - h, 26, h), { position: 'absolute', borderRadius: '6px 6px 0 0',
  transformOrigin: '50% 100%', background: i === 6 ? 'linear-gradient(180deg,#8fc4ff,#3f7fd6)' : 'rgba(255,255,255,.22)' }), cnt));
const decl = tx(24, 216, 'declined today · <span style="color:rgba(255,255,255,.8)">0</span>', { size: 16, weight: 500, parent: cnt, color: 'rgba(255,255,255,.55)' }, 20);
const declN = decl.querySelector('span');

/* ---------- SUPPORT: avatar discs at the phone's left edge ---------- */
const DX = 392, DD = 50, discCY = [449, 503, 557];
const mkDisc = (i, k) => {
  const e = ava(DX, discCY[i] - DD / 2, DD, k, mid, '0 6px 14px rgba(0,0,0,.5)');
  Object.assign(e.style, { border: '3px solid #0a0b0f', outline: '1.5px solid rgba(255,255,255,.35)' });
  return e;
};
const dKai = mkDisc(0, 4), dNova = mkDisc(1, 7), dTre = mkDisc(2, 1);
const link = (i, t) => R3.connect([DX + DD, discCY[i]], [PX + 4, rowCY(i)], t, { svg, color: 'rgba(255,255,255,.4)', w: 1.5, curve: .2, d: .35 });

/* ================= TIMELINE ================= */
// w0 — major: phone settles, left panels + first row
R3.ft(phone, { autoAlpha: 0, scale: .92, y: 18 }, { autoAlpha: 1, scale: 1, y: 0, duration: .8, ease: 'power3.out' }, S);
R3.appear([cal, cnt], S + .1, { y: 20, stagger: .1, d: .5 });
R3.appear(sqs, S + .28, { y: 0, scale: .6, d: .35, stagger: .08 });
R3.appear(mira.r, T(0), { y: 14, scale: .97, d: .4 });
tl.set(stamp, { rotation: -7 }, S);
tl.set([bigAva], { autoAlpha: 0, x: -157, y: -63, scale: .347 }, S);
tl.set([bigName, bigSub, plus], { autoAlpha: 0 }, S);
tl.set(bars[6], { scaleY: .72 }, S);

// w1 — row 2
R3.appear(jay.r, T(1), { y: 14, scale: .97, d: .4 });
// w3 — row 3 + quit chip
R3.appear(lexi.r, T(3), { y: 14, scale: .97, d: .4 });
R3.appear(quitChip, T(3) + .06, { y: 10, scale: .9, d: .45 });

// w8 — jayden goes inactive
tl.to(jay.r, { filter: 'grayscale(1)', opacity: .5, duration: .4, ease: 'sine.inOut' }, T(8));
swap(jay.pv, T(8), 'last active 6w ago');
swap(jay.tm, T(8), '6w');

// w12 — major: lexi deactivated, calendar freezes (last day hatched)
tl.to(lexi.r, { filter: 'grayscale(1)', opacity: .45, duration: .4, ease: 'sine.inOut' }, T(12));
swap(lexi.pv, T(12), 'account deactivated');
swap(lexi.tm, T(12), '—');
R3.ft(sqs, { filter: 'grayscale(0) brightness(1)' }, { filter: 'grayscale(1) brightness(.72)', duration: .45, ease: 'sine.inOut', stagger: .06 }, T(12) + .04);
R3.ft(ice, { autoAlpha: 0 }, { autoAlpha: 1, duration: .45, ease: 'sine.inOut', stagger: .06 }, T(12) + .04);
swap(calS, T(12) + .04, 'paused');
tl.to(calS, { color: 'rgba(255,255,255,.45)', duration: .18 }, T(12) + .16);

// w16 — the one camera move: eased step-in toward the inbox, then hold
tl.set(ctx.cam.el, { transformOrigin: '760px 567px' }, S);
ctx.cam.push(T(16), 1.1, 1.04);

// w17 — @kai.makes lands on top, disc joins
tl.to(older, { y: PITCH, duration: .38, ease: 'power3.out' }, T(17));
R3.appear(kai.r, T(17) + .08, { y: -14, scale: .97, d: .38, ease: 'back.out(1.4)' });
R3.appear(dKai, T(17) + .14, { y: 0, x: -10, scale: .6, d: .38 });
link(0, T(17) + .2);

// w20 — @nova.lux
tl.to(older, { y: PITCH * 2, duration: .18, ease: 'power2.out' }, T(20));
R3.appear(nova.r, T(20) + .06, { y: -12, scale: .97, d: .36, ease: 'back.out(1.4)' });
R3.appear(dNova, T(20) + .1, { y: 0, x: -10, scale: .6, d: .36 });
const lNova = link(1, T(20) + .14);

// w22 — @tre.visuals, counter rolls 38 → 41
tl.to(older, { y: PITCH * 3, duration: .32, ease: 'power3.out' }, T(22));
R3.appear(tre.r, T(22) + .08, { y: -12, scale: .97, d: .38, ease: 'back.out(1.4)' });
R3.appear(dTre, T(22) + .12, { y: 0, x: -10, scale: .6, d: .38 });
const lTre = link(2, T(22) + .16);
R3.count(appCount, T(22) + .12, .6, 38, 41);
R3.count(bigNum, T(22) + .12, .6, 38, 41);
R3.appear(plus, T(22) + .2, { y: 8, scale: .85, d: .4 });
R3.ft(bars[6], { scaleY: .72 }, { scaleY: 1, duration: .45, ease: 'back.out(1.6)' }, T(22) + .16);

// w27 — red decline stamp on the top row; avatar starts to enlarge
R3.ft(stamp, { autoAlpha: 0, scale: 1.7, rotation: -16 }, { autoAlpha: 1, scale: 1, rotation: -7, duration: .38, ease: 'back.out(1.8)' }, T(27));
tl.to([kai.tm, kai.dot], { autoAlpha: 0, duration: .15 }, T(27));
tl.to(kai.r, { borderColor: 'rgba(255,77,94,.55)', backgroundColor: 'rgba(255,77,94,.07)', duration: .3 }, T(27));
tl.to(kai.av, { scale: 1.18, duration: .5, ease: 'back.out(1.5)' }, T(27) + .1);
tl.to(dKai, { outlineColor: 'rgba(255,77,94,.9)', duration: .3 }, T(27));
swap(declN, T(27) + .1, '1');
tl.to(declN, { color: '#ff4d5e', duration: .18 }, T(27) + .22);

// w33 — inbox clears, kai avatar grows into the profile-picture position (match-cut setup)
tl.to([mira.r, jay.r, lexi.r, nova.r, tre.r], { autoAlpha: 0, duration: .3, ease: 'power2.in' }, T(33));
tl.to([dNova, dTre, lNova, lTre], { opacity: .25, duration: .3 }, T(33));
tl.set(bigAva, { autoAlpha: 1 }, T(33));
tl.set(kai.av, { autoAlpha: 0 }, T(33));
tl.to(bigAva, { x: 0, y: 0, scale: 1, duration: .85, ease: 'power3.inOut' }, T(33));
R3.appear([bigName, bigSub], T(33) + .45, { y: 10, d: .4, stagger: .08 });

