/* ===== The empty shelf: @kai.makes profile → repost flood → empty grid ===== */
const RED = '#e8283c';
const at = (i, d = 0.05) => W[i] - d;
const T = (x, y, html, o = {}) => {
  const e = R3.text(x, y, html, o);
  e.style.lineHeight = o.lh || '1.15';
  e.style.whiteSpace = 'nowrap';
  if (o.ls) e.style.letterSpacing = o.ls;
  if (o.shadow) e.style.textShadow = '0 1px 4px rgba(0,0,0,.6)';
  return e;
};

/* flat avatar: R3.avatar restyled with a LINEAR fill (no radial gradient) */
const PAL = [['#ff6b6b', '#5f27cd'], ['#feca57', '#ff6b6b'], ['#48dbfb', '#0abde3'], ['#1dd1a1', '#10ac84'], ['#a29bfe', '#6c5ce7'],
  ['#fd79a8', '#e84393'], ['#fab1a0', '#e17055'], ['#81ecec', '#00cec9'], ['#ffeaa7', '#fdcb6e'], ['#74b9ff', '#0984e3']];
const AVA = (x, y, d, k, parent) => {
  const a = R3.avatar(x, y, d, k, parent);
  const [c1, c2] = PAL[(k + 3) % PAL.length];
  a.style.background = `linear-gradient(145deg, ${c1} 0%, ${c2} 100%)`;
  a.style.backgroundImage = `linear-gradient(145deg, ${c1} 0%, ${c2} 100%)`;
  return a;
};

/* ---------------- PHONE (hero) ---------------- */
const PX = 590, PY = 320, PW = 430, PH = 503;
const phone = R3.card(PX, PY, PW, PH, null, {
  borderRadius: '48px', border: '4px solid rgba(255,255,255,.8)', boxSizing: 'border-box'
});
const scr = R3.mk('div', 'r3-screen', Object.assign(R3.box(10, 10, 402, 475), {
  position: 'absolute', overflow: 'hidden', borderRadius: '38px', background: '#0c0c10'
}), phone);
scr.dataset.device = '1';

// scrollable page content (pushed into on w58)
const SCROLL = 236;
const pg = R3.mk('div', '', Object.assign(R3.box(0, 0, 402, 720), { position: 'absolute' }), scr);

// profile block (fades out as it scrolls away, so nothing ever leaves the screen)
const ava = AVA(16, 92, 84, 1, pg);
Object.assign(ava.style, { boxSizing: 'border-box', border: '3px solid rgba(255,255,255,.85)', boxShadow: '0 6px 14px rgba(0,0,0,.5)' });

const statEls = [];
[['2', 'posts'], ['412', 'followers'], ['1,038', 'following']].forEach(([v, l], i) => {
  const x = 112 + i * 96;
  statEls.push(T(x, 104, v, { size: 26, weight: 800, w: 92, align: 'center', parent: pg }));
  statEls.push(T(x, 142, l, { size: 14, weight: 500, w: 92, align: 'center', color: 'rgba(255,255,255,.55)', parent: pg }));
});
const nameEl = T(16, 184, 'Kai Mendes', { size: 21, weight: 800, parent: pg });
const handleEl = T(16, 217, '@kai.makes', { size: 16, weight: 500, color: 'rgba(255,255,255,.55)', parent: pg });
const bioEl = T(16, 244, 'producer · ATL', { size: 16, weight: 500, color: 'rgba(255,255,255,.85)', parent: pg });

const btn = (x, w, label, bg, col) => R3.mk('div', 'r3-el', Object.assign(R3.box(x, 272, w, 34), {
  position: 'absolute', borderRadius: '10px', background: bg, color: col, fontSize: '15px', fontWeight: '700',
  lineHeight: '34px', textAlign: 'center'
}), pg, label);
const bFollow = btn(16, 180, 'Follow', '#ffffff', '#0c0c10');
const bMsg = btn(204, 182, 'Message', 'rgba(255,255,255,.12)', '#ffffff');

const tabs = ['Posts', 'Reels', 'Tagged'].map((l, i) =>
  T(i * 134, 320, l, { size: 14, weight: 700, w: 134, align: 'center', color: i ? 'rgba(255,255,255,.45)' : '#fff', parent: pg }));
const tabHair = R3.mk('div', '', Object.assign(R3.box(0, 344, 402, 1), { position: 'absolute', background: 'rgba(255,255,255,.14)' }), pg);
const tabLine = R3.mk('div', 'r3-el', Object.assign(R3.box(22, 342, 90, 2), { position: 'absolute', background: '#fff', borderRadius: '2px' }), pg);

// post grid: 4 x 3, two real thumbs + ten dashed empties (fits the screen after the scroll)
const CW = 95, CH = 114;
const cx = (q) => 5 + q * 99, cy = (r) => 352 + r * 120;
const TH = [{ label: 'Reel · Mar 2', views: '1,104 views', k: 4 }, { label: 'Reel · Mar 19', views: '866 views', k: 9 }];
const thumbs = [], empties = [];
for (let i = 0; i < 12; i++) {
  const q = i % 4, r = Math.floor(i / 4);
  if (i < 2) {
    const th = R3.thumb(cx(q), cy(r), CW, CH, TH[i].k, { parent: pg });
