    thumbs.push(th);
  } else {
    empties.push(R3.mk('div', 'r3-el', Object.assign(R3.box(cx(q), cy(r), CW, CH), {
      position: 'absolute', boxSizing: 'border-box', borderRadius: '6px',
      border: '1.5px dashed rgba(255,255,255,.28)', background: 'rgba(255,255,255,0.02)'
    }), pg));
  }
}
const day1 = T(0, 47, 'Day 1', { size: 15, weight: 800, w: CW, align: 'center', parent: empties[0] });

// sticky header (notch + nav + repost pill dock)
const hdr = R3.mk('div', '', Object.assign(R3.box(0, 0, 402, 80), {
  position: 'absolute', background: '#0c0c10', borderBottom: '1px solid rgba(255,255,255,.06)', boxSizing: 'border-box'
}), scr);
R3.mk('div', '', Object.assign(R3.box(153, 8, 96, 24), { position: 'absolute', borderRadius: '14px', background: '#000' }), hdr);
const navBack = T(16, 40, '‹', { size: 28, weight: 500, parent: hdr, lh: '1' });
const navMore = T(360, 48, '•••', { size: 14, weight: 800, parent: hdr, lh: '1', color: 'rgba(255,255,255,.8)' });
const pill = R3.mk('div', 'r3-el', Object.assign(R3.box(51, 40, 300, 34), {
  position: 'absolute', borderRadius: '17px', background: RED, color: '#fff', fontSize: '15px', fontWeight: '700',
  lineHeight: '34px', textAlign: 'center', whiteSpace: 'nowrap', boxShadow: '0 8px 20px rgba(0,0,0,.45)'
}), hdr, '↻&nbsp; Reposted by @bigstage · 2.1M');

/* ---------------- LEFT: insights card (counter + sparkline) ---------------- */
const ins = R3.card(76, 320, 480, 300);
